import { z } from "zod";
import { api } from "@/lib/api/handler";

/** POST /api/v1/violations/{id}/payment — method is a payment-method code (or one of the two older names). The reference is generated by the database: <CODE>-<YEAR>-<number>. */
export const POST = api({ body: z.object({ method: z.string().trim().min(3).max(20), reference: z.string().trim().max(500).optional(), paidAt: z.string().regex(/^\d{4}-\d{2}-\d{2}$/), idempotencyKey: z.string().min(8).max(100) }) }, async ({ actor, body, params, rpc }) =>
  rpc("record_violation_payment", { p_actor: actor.id, p_violation: params.id, p_method: body.method, p_reference: body.reference ?? null, p_paid_at: body.paidAt, p_idempotency_key: body.idempotencyKey }));
